#include <bits/stdc++.h>
using namespace std;

const int MAX = 2e5 + 10;

int ar[MAX];
int n, m, k;

int find(int pos){
    int ans = n - pos + 1;
    int used = 0;
    while(used < m && pos <= n){
        int t = k;
        while(pos <= n && ar[pos] <= t){
            t -= ar[pos++];
        }
        used++;
    }
    return pos == n + 1 ? ans : 0;
}

int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> n >> m >> k;
    for(int i = 1; i <= n; i++){
        cin >> ar[i];
    }
    int ans = 0;
    int l = 1, r = n;
    while(l <= r){
        int x = (l + r) >> 1;
        if(find(x)){
            ans = max(ans, n - x + 1);
            r = x - 1;
        }else{
            l = x + 1;
        }
    }
    cout << ans << endl;
}

